<?php namespace App\Models;use Illuminate\Database\Eloquent\Model;class Payout extends Model{protected $fillable=['seller_id','amount_minor','status','method','reference','reason','reviewed_by','reviewed_at','paid_at'];protected function casts():array{return['amount_minor'=>'integer','reviewed_at'=>'datetime','paid_at'=>'datetime'];}public function seller(){return $this->belongsTo(Seller::class);} }
